<?php require 'config.php'; require 'lib.php'; need_login(); track_user(); csrf_check(); if($_SERVER['REQUEST_METHOD']==='POST'&&!is_admin()){ http_response_code(403); exit(t('Du har bara läsbehörighet.','You have read-only access.')); }
$TY=st_types(); $RO=st_roles();
function nconn0($old){ $c=['snmp'=>snmp_param_build($_POST['s_ver']??'2',$_POST,$old['snmp']??'')]; if(($_POST['type']??'')==='truenas'){ $t=$old['tn']??[]; $k=trim($_POST['tn_key']??''); if($k!==''&&$k!=='********') $t['key']=secret_enc($k); $pt=(int)preg_replace('/\D/','',$_POST['tn_port']??''); $t['port']=$pt?:($t['port']??443); $t['verify']=!empty($_POST['tn_verify'])?1:0; if(!empty($t['key'])) $c['tn']=$t; } return $c; }
function nconn($old){ return nw_conn_iv(nconn0($old)); }
function nrole(){ $r=$_POST['role']??''; return isset(st_roles()[$r])?$r:'nas'; }
if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['a']??''; $hid=(int)($_POST['id']??$_POST['cid']??0); $pdo=db();
 if($a==='add'&&isset($TY[$_POST['type']??''])&&trim($_POST['host']??'')!==''){ $h=trim($_POST['host']);
  $pdo->prepare('INSERT INTO servers(name,host,nw_type,nw_role,nw_conn) VALUES(?,?,?,?,?)')->execute([trim($_POST['name']??'')?:$h,$h,$_POST['type'],nrole(),json_encode(nconn([]))]); $nid=$pdo->lastInsertId();
  $pdo->prepare("INSERT INTO server_checks(server_id,source,kind,target,label) VALUES(?,'tcp','ping','','Ping')")->execute([$nid]); applog('info','config','Storage device added: '.$h); $_SESSION['flash']=t('Enhet tillagd – första SNMP-avläsningen sker inom en minut (klicka på Testa nu för att se felmeddelanden direkt).','Device added – the first SNMP reading happens within a minute (click Test now to see any error right away).'); }
 if($a==='edit'&&isset($TY[$_POST['type']??''])&&trim($_POST['host']??'')!==''){ $q2=$pdo->prepare('SELECT nw_conn FROM servers WHERE id=?'); $q2->execute([$hid]); $old=json_decode((string)$q2->fetchColumn(),true)?:[]; $h=trim($_POST['host']);
  $pdo->prepare('UPDATE servers SET name=?,host=?,comment=?,nw_type=?,nw_role=?,nw_conn=?,nw_poll=NULL WHERE id=? AND nw_type IS NOT NULL')->execute([trim($_POST['name']??'')?:$h,$h,trim($_POST['comment']??''),$_POST['type'],nrole(),json_encode(nconn($old)),$hid]); }
 if($a==='test'){ $q=$pdo->prepare('SELECT * FROM servers WHERE id=? AND nw_type IS NOT NULL'); $q->execute([$hid]); if($s=$q->fetch()){ $r=poll_network($s); $_SESSION['flash']=$r['ok']?('✔ '.$s['name'].': CPU '.($r['data']['cpu']!==null?$r['data']['cpu'].'%':'–').', '.t('minne','memory').' '.($r['data']['mem']!==null?$r['data']['mem'].'%':'–').', '.count($r['ifs']).' interface'):('✖ '.$s['name'].': '.$r['error']); } }
 if($a==='toggle'){ $pdo->prepare('UPDATE servers SET enabled=1-enabled,nw_poll=NULL WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]); $pdo->prepare('UPDATE server_checks SET last_check=NULL WHERE server_id=?')->execute([$hid]); }
 if($a==='toggle_dash') $pdo->prepare('UPDATE servers SET dash_hidden=1-dash_hidden WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]);
 if($a==='del'){ applog('warning','config','Storage device deleted, id '.$hid); $q=$pdo->prepare('SELECT id FROM server_checks WHERE server_id=?'); $q->execute([$hid]); purge_targets([$hid],array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN))); $pdo->prepare('DELETE FROM servers WHERE id=? AND nw_type IS NOT NULL')->execute([$hid]); }
 header('Location: '.((($_POST['back']??'')==='detail'&&$a!=='del')?'netdev.php?id='.$hid:'storage.php'));exit; }
$ed=null; $ec=[]; if(isset($_GET['edit'])&&is_admin()){ $q=db()->prepare('SELECT * FROM servers WHERE id=? AND nw_type IS NOT NULL'); $q->execute([(int)$_GET['edit']]); $ed=$q->fetch()?:null; $ec=$ed?(json_decode((string)$ed['nw_conn'],true)?:[]):[]; }
