<?php foreach(db()->query("SELECT s.*,TIMESTAMPDIFF(SECOND,nw_poll,NOW()) AS age,(SELECT last_status FROM server_checks c WHERE c.server_id=s.id AND c.kind='ping' LIMIT 1) ping,(SELECT COUNT(*) FROM net_if n WHERE n.server_id=s.id) nif,(SELECT COUNT(*) FROM net_if n WHERE n.server_id=s.id AND n.oper=1) nup FROM servers s WHERE s.nw_type IS NOT NULL AND s.nw_role IN ('nas','san') ORDER BY s.name") as $s): $d=json_decode((string)$s['nw_data'],true)?:[]; $en=(int)$s['enabled']===1; ?>
