<td class="<?= $s['ping']==='up'?'okt':($s['ping']?'badt':'') ?>"><?= $s['ping']?:t('väntar','pending') ?></td><td class="det <?= $s['nw_status']==='up'?'okt':($s['nw_status']?'badt':'') ?>"><?= (json_decode((string)$s['nw_conn'],true)['snmp']??'')==='none'?'<span class="mut">'.t('av','off').'</span>':'' ?><?= $s['nw_status']?h($s['nw_status']).($s['nw_error']?' – '.h($s['nw_error']):''):t('väntar','pending') ?></td><td><?php $tt=0; $uu=0; foreach($d['disks']??[] as $x){ $tt+=$x['t']; $uu+=$x['t']-$x['f']; } echo $tt>0?gb($uu).' / '.gb($tt).' ('.round($uu/$tt*100).'%)':'–'; ?></td><td><?php $hl=$d['health']??[]; $hb=count(array_filter($hl,fn($x)=>$x['st']!=='ok')); echo $hl?'<span class="'.($hb?'badt':'okt').'">'.($hb?$hb.' '.t('avviker','not OK'):count($hl).' OK').'</span>':'–'; ?></td><td><?php $sm=$d['smart']??[]; $bd=count(array_filter($sm,fn($x)=>in_array($x['st'],['warn','fail'],true))); echo $sm?'<span class="'.($bd?'badt':'okt').'">'.($bd?$bd.' '.t('varnar/felar','warn/fail'):count($sm).' OK').'</span>':'–'; ?></td><td><?= $s['age']===null?'–':($s['age']<60?$s['age'].' s':floor($s['age']/60).' min') ?></td>
